async def execute(task_id, module_name, usecase):
    """Länka modul + use case till task (om fälten finns)."""
    task = env['project.task'].sudo().browse(int(task_id))
    if not task.exists():
        return 'Task %s not found' % task_id
    vals = {}
    if 'ai_plan' in task._fields:
        vals['ai_plan'] = 'Modul: %s\n\n%s' % (module_name, usecase)
    if 'ai_usecase' in task._fields:
        vals['ai_usecase'] = '<p>%s — <b>%s</b></p>' % (usecase, module_name)
    if not vals:
        return 'ai_plan/ai_usecase-fält saknas (installera project_ai_plan)'
    task.write(vals)
    # Kostnadskontext (5.4)
    env['ai.coworker']._capture_session_from_task(task.id)
    return 'Task %s kopplad till modul %s' % (task.name, module_name)

async def execute(task_id, description=None, priority=None):
    """Uppdatera beskrivning/prioritet på task."""
    task = env['project.task'].sudo().browse(int(task_id))
    if not task.exists():
        return 'Task %s not found' % task_id
    vals = {}
    if description is not None:
        vals['description'] = str(description)
    if priority is not None:
        vals['priority'] = int(priority)
    if not vals:
        return 'Inga fält att uppdatera'
    task.write(vals)
    # Kostnadskontext (5.4)
    env['ai.coworker']._capture_session_from_task(task.id)
    return 'Task %s uppdaterad' % task.name

async def execute():
    """Läs sessionens kostnadskontext."""
    sess = env['ai.coworker.session'].browse(0)
    if env.context.get('_ai_context_model') == 'ai.coworker.session':
        sess = env['ai.coworker.session'].browse(
            int(env.context.get('_ai_context_id') or 0))
    if not sess.exists():
        return json.dumps({'error': 'Ingen aktiv session'})
    def _name(f):
        return (sess[f].name if f in sess._fields and sess[f] else '')
    return json.dumps({
        'project_id': sess.project_id.id if 'project_id' in sess._fields and sess.project_id else None,
        'project_name': _name('project_id'),
        'task_id': sess.task_id.id if 'task_id' in sess._fields and sess.task_id else None,
        'task_name': _name('task_id'),
        'partner_id': sess.partner_id.id if sess.partner_id else None,
        'partner_name': _name('partner_id'),
        'cost_context_confirmed': sess.cost_context_confirmed,
    }, ensure_ascii=False, default=str)

async def execute(project_id=None, task_id=None, partner_id=None):
    """Sätt kostnadskontext och bekräfta en gång per session."""
    sess = env['ai.coworker.session'].browse(0)
    if env.context.get('_ai_context_model') == 'ai.coworker.session':
        sess = env['ai.coworker.session'].browse(
            int(env.context.get('_ai_context_id') or 0))
    if not sess.exists():
        return 'Ingen aktiv session'
    if 'project_id' in sess._fields or 'task_id' in sess._fields:
        # Domänfält finns (project_ai installerat) — använd bryggans
        # skrivpunkt + resolver-strategi.
        sess._capture_context(task=task_id, project=project_id,
                              partner=partner_id)
        sess._apply_cost_context_strategy()
    elif partner_id:
        sess.partner_id = int(partner_id)
    sess.cost_context_confirmed = True
    sess.write({'cost_context_confirmed': True})
    def _name(f):
        return (sess[f].name if f in sess._fields and sess[f] else '?')
    return 'Kostnadskontext satt: projekt=%s, uppgift=%s, kund=%s (bekräftad)' % (
        _name('project_id'), _name('task_id'), _name('partner_id'))
